{
  "name": "es_search",
  "description": "Search an Elasticsearch index. Query is \"field==value && other~text\" (== term, ~ match) or raw JSON DSL. Returns a preview plus `view`, a link to the full result as an interactive table (shown to the user inline). Mention the link.",
  "group": "es",
  "origin": "built-in",
  "execution": {
    "protocol": "dt.tool/v1",
    "transport": "in-process"
  },
  "inputSchema": {
    "type": "object",
    "properties": {
      "index": {
        "type": "string",
        "description": "Index or alias"
      },
      "query": {
        "type": "string",
        "description": "Query"
      },
      "env": {
        "type": "string",
        "enum": [
          "dev",
          "fixture"
        ],
        "default": "dev",
        "description": "Environment"
      },
      "size": {
        "type": "integer",
        "description": "Hits",
        "default": 20
      }
    },
    "required": [
      "index"
    ]
  }
}
